<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT o.*,u.name buyer,u.email FROM orders o JOIN users u ON u.id=o.buyer_id WHERE o.id=?');$st->execute([$id]);$o=$st->fetch();if(!$o||((int)$o['buyer_id']!==(int)current_user()['id']&&current_user()['role']!=='admin')){http_response_code(404);exit('Receipt not found.');}$st=$pdo->prepare('SELECT oi.*,p.name,p.unit FROM order_items oi JOIN produce p ON p.id=oi.produce_id WHERE oi.order_id=?');$st->execute([$id]);$items=$st->fetchAll();include __DIR__.'/includes/header.php'; ?><section class="section receipt"><div class="receipt-top"><div><span class="eyebrow">AGRIHUB</span><h1>Order receipt #<?= $o['id'] ?></h1><p>Thank you for supporting local farmers.</p></div><button class="btn no-print" onclick="window.print()">Print / Save PDF</button></div><p><b>Buyer:</b> <?= e($o['buyer']) ?> (<?= e($o['email']) ?>)<br><b>Date:</b> <?= e($o['created_at']) ?><br><b>Status:</b> <?= e(ucfirst($o['status'])) ?></p><div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['name']) ?></td><td><?= (int)$i['quantity'] ?> <?= e($i['unit']) ?></td><td>KSh <?= number_format($i['unit_price'],2) ?></td><td>KSh <?= number_format($i['unit_price']*$i['quantity'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><h2 class="receipt-total">Total: KSh <?= number_format($o['total'],2) ?></h2><p class="muted">This receipt can be printed or saved as PDF using your browser.</p></section><?php include __DIR__.'/includes/footer.php'; ?>